# Creates the FlashGuard QA tooling files.
# Usage (from the FlashGuard folder):  powershell -ExecutionPolicy Bypass -File .\install-qa-tooling.ps1
# Existing files are NOT overwritten unless you add -Force.
param([switch]$Force)
if (-not (Test-Path 'package.json')) { Write-Error 'Run this from the FlashGuard folder (the one with package.json)'; exit 1 }
$files = [ordered]@{
  'scripts\run-all.ps1' = ''
  'scripts\sonar-scan.ps1' = ''
  'scripts\upload-testmo.ps1' = ''
  'scripts\qa-metrics.mjs' = ''
  'scripts\rtm.mjs' = ''
  'docs\defect-log.csv' = ''
  '.github\workflows\qa.yml' = ''
  'eslint.config.mjs' = ''
  'sonar-project.properties' = ''
  'docker-compose.sonar.yml' = ''
}
foreach ($path in $files.Keys) {
  $dir = Split-Path $path -Parent
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  if ((Test-Path $path) -and -not $Force) { Write-Host "SKIP    $path (already exists, use -Force to overwrite)" -ForegroundColor Yellow; continue }
  [IO.File]::WriteAllBytes((Join-Path (Get-Location) $path), [Convert]::FromBase64String($files[$path]))
  Write-Host "CREATED $path" -ForegroundColor Green
}
Write-Host "`nDone. Next: npm i -D eslint @eslint/js typescript-eslint eslint-plugin-playwright allure-playwright @wdio/allure-reporter @wdio/junit-reporter newman allure-commandline @testmo/testmo-cli"
Write-Host 'Then:  .\scripts\run-all.ps1 -Layers lint'
